/* ===================== fin de la lección ===================== */
function terminarLeccion() {
  $$('.combo').forEach((e) => e.remove());
  const antes = {}; INSIGNIAS.forEach((i) => { antes[i.id] = nivelDe(i, i.valor()); });
  const piezasAntes = new Set(todasPiezas().filter(piezaTiene).map((p) => p.id));
  const bono = 10; const total = L.monedas + bono;
  const rachaAntes = estado.racha; const rachaSube = estado.ultimaFecha !== hoyISO();
  const monedasAntes = estado.monedas;
  estado.monedas += total; estado.contadores.retos += L.aciertos; estado.hoyMin += 4;
  if (rachaSube) { estado.racha++; estado.ultimaFecha = hoyISO(); }
  if (L.idx === estado.hechas) estado.hechas++;
  const nuevas = INSIGNIAS.filter((i) => nivelDe(i, i.valor()) > antes[i.id]).map((i) => ({ ins: i, nivel: nivelDe(i, i.valor()) }));
  const piezasNuevas = todasPiezas().filter((p) => piezaTiene(p) && !piezasAntes.has(p.id));
  estado.nuevas = (estado.nuevas || []).concat(nuevas.map((n) => n.ins.id));
  guardar(); refrescar();
  renderFin({ total, monedasLeccion: L.monedas, bono, aciertos: L.primeros, de: LECCIONES[L.idx].length, racha: estado.racha, rachaAntes, rachaSube, nuevas, piezasNuevas, monedasAntes });
  go('fin');
  animarFin({ total, aciertos: L.primeros, de: LECCIONES[L.idx].length, racha: estado.racha, rachaAntes, rachaSube, nuevas });
}
